/* What kind of dancing each move belongs to, so that a routine, or a journey, can keep to one kind. Every move is
   in exactly one list (tools/unit.mjs checks). */
export const MV_STYLES={
 groove:["sway","step touch","step clap","groove","snap","hip sway","shoulder lean","body roll","b-boy rock","shimmy","heel toe","box step","rock step","slow clap","lean back","lean and rock","hip bump","hands up","raise the roof","fist pump","pogo","overhead clap","get low","stadium wave","finger wag","jazz hands"],
 disco:["disco point","hand roll","spin","y m c a","electric slide","skate","temptation walk","lightbulb","arm wave","hustle","bus stop","roller coaster"],
 sixties:["twist","swim","mashed potato","monkey","pony","hitchhiker","the jerk","watusi","freddie","locomotion","hand jive","batusi","funky chicken","backstroke","hula","limbo","conga","charleston","suzie q","elvis","jagger","bunny hop","hokey pokey","time warp","chicken"],
 hiphop:["running man","cabbage patch","robot","dougie","stanky leg","bernie","whip","dab","floss","gangnam","the woah","milly rock","butterfly","tootsie roll","harlem shake","king tut","smurf","wop","steve martin","humpty","roger rabbit","top rock","walk it out","bankhead bounce","shoot","orange justice","jump on it","superman","hammer time","krump","moonwalk","moonwalker kick","kick step","take the l","best mates","lock","scooby doo","wrist roll","chest pop","glide","tutting","boogaloo","slow mo","nae nae","hit the quan","griddy","swag surf"],
 party:["shopping cart","lawnmower","macarena","sprinkler","big fish little fish","driving","snoopy","reel them in","stir the pot","air guitar","elaine","tequila","carlton","egyptian","thriller","vogue","single ladies","bye bye bye","cha cha slide","cupid shuffle","wobble","boxing","jump rope","cheerleader","windmill arms","headbang","duck walk","lasso","pizza toss","bowling","churn the butter","wax on wax off","kung fu","flex","titanic","catwalk","fosse","soft shoe","peace","rope pull","skipping","squat","zumba","shrug"],
 world:["grapevine","salsa","samba","flamenco","zorba","belly dance","riverdance","cossack","can-can","jazz square","kick ball change","heel click","merengue","bachata","cumbia","mambo","tango","polka","hora","highland fling","haka","hula hands","dabke","ginga","gumboot","azonto","gwara gwara","bogle","time step","jitterbug","pirouette","arabesque","plie"],
 rave:["lasers","shuffle","jumpstyle","tecktonik","skank","high knees","skier","star jump","t-step","cutting shapes","big box little box","stacking shelves","double pump","glowsticks","liquid","hakken","rave stomp","melbourne bounce","hands in the air","heart hands","trance arms","the drop","spongebob","kick side step","poi","phone light","techno march","hardstyle kick","wobble bass","airhorn","dj","push the walls","bounce clap","chop"],
 breaking:["indian step","salsa rock","bronx step","hook","power step","uprock","brooklyn rock","apple jack","six step","three step","cc","kick out","coffee grinder","sweep","floor rock","knee drop","baby freeze","chair freeze","freeze","zulu spin","scissor kicks","kip up"],
 indian:["bhangra","balle balle","bhangra shoulders","dhol","jhummar","giddha","garba","dandiya","thumka","pat the dog","kathak spin","aramandi","tatta adavu","natta adavu","namaste","nagin","sundari","lotus hands","kite","ghoomar","lavani","bolly shrug","raas","lezim","mudra arms"]
};
/* the kind a move belongs to ("" if it is in no list); found once and kept in the move */
export function moveStyle(m){
  var k;
  if(m.style===undefined){m.style="";for(k in MV_STYLES)if(MV_STYLES[k].indexOf(m.name)>=0)m.style=k;}
  return m.style;
}
/* the same pose facing the other way: left and right change places */
export function flipPose(o){
  var i,t;o[0]=-o[0];o[4]=-o[4];o[5]=-o[5];o[6]=-o[6];o[7]=-o[7];o[8]=-o[8];o[10]=-o[10];
  for(i=0;i<4;i++){t=o[12+i];o[12+i]=o[16+i];o[16+i]=t;t=o[20+i];o[20+i]=o[24+i];o[24+i]=t;}
  return o;
}
/* a key as a whole pose: standing, with what the key names put in */
function keyPose(k){
  var o=MV_REST.slice(),at={x:0,z:1,d:2,hop:3,turn:4,py:5,pr:6,tw:7,ls:8,lf:9,ht:10,hn:11},n;
  for(n in at)if(k[n]!==undefined)o[at[n]]=k[n];
  if(k.B){set4(o,12,k.B);set4(o,16,k.B);}
  if(k.L)set4(o,12,k.L);
  if(k.R)set4(o,16,k.R);
  if(k.fl)set4(o,20,k.fl);
  if(k.gr)set4(o,24,k.gr);
  return o;
}
/* a move's keys as whole poses in order, ending with the pose at beat len; made once and kept in the move */
export function moveKeys(m){
  var ks,i,h;
  if(m.k)return m.k;
  ks=m.keys.map(function(k){return {t:k.t,a:keyPose(k)}});
  if(m.sym){h=m.len/2;m.keys.forEach(function(k){ks.push({t:k.t+h,a:flipPose(keyPose(k))})});}
  if(ks[ks.length-1].t<m.len)ks.push({t:m.len,a:ks[0].a});else m.ends=1;
  m.k=ks;return ks;
}
/* The pose of move m at beat u, into o. A move that says how long to wait at each key (hold), or snaps (hit), or ends
   on a key of its own, goes from key to key eased, stopping at each. Any other flows: its numbers pass through each
   key at the speed that carries them on to the next (a curve through the keys with no corners), so the figure does
   not stop on every beat. The give of the knees on the beat is not in here: js/dance.js adds it from the sound. */
export function movePose(m,u,o){
  var ks=moveKeys(m),n=ks.length-1,uu=u-m.len*Math.floor(u/m.len),i=0,j,w,h=m.hold||0,a,b,p,q,t0,t1,tp,tq,dt,w2,w3,ma,mb;
  while(i<n-1&&ks[i+1].t<=uu)i++;
  a=ks[i].a;b=ks[i+1].a;t0=ks[i].t;t1=ks[i+1].t;dt=Math.max(1e-6,t1-t0);
  w=(uu-t0)/dt;
  if(h>0||m.hit||m.ends){
    w=ease((w-h)/(1-h));if(m.hit)w=ease(w);
    for(j=0;j<MV_N;j++)o[j]=a[j]+(b[j]-a[j])*w;
  }else{
    /* the key before this pair and the key after it, going round the end of the move */
    p=i>0?ks[i-1]:ks[n-1];tp=i>0?p.t:p.t-m.len;q=i+2<=n?ks[i+2]:ks[1];tq=i+2<=n?q.t:q.t+m.len;
    w2=w*w;w3=w2*w;
    for(j=0;j<MV_N;j++){
      ma=(b[j]-p.a[j])/(t1-tp)*dt;mb=(q.a[j]-a[j])/(tq-t0)*dt;
      o[j]=(2*w3-3*w2+1)*a[j]+(w3-2*w2+w)*ma+(3*w2-2*w3)*b[j]+(w3-w2)*mb;
    }
    o[2]=Math.max(0,o[2]);o[3]=Math.max(0,o[3]);
  }
  if(m.post)m.post(uu,o);
  return o;
}
/* how far a move's knees give on each beat */
export function moveBob(m){return m.bob===undefined?0.024:m.bob;}
/* How fast a move carries the figure along the floor at beat u, in figure heights a beat, to the figure's own left
   (0 for most moves). go is the speed; a move with sway turns back every sway beats, so that it goes to and fro. */
export function moveGo(m,u){return m.go?m.go*(m.sway&&Math.floor(u/m.sway)%2?-1:1):0;}

/* for the test tools and the browser console: every name in this file; the ones that can change have a getter and a setter */
export const __dbg={MV_N, MV_REST, MOVES, MV_STYLES, moveStyle, flipPose, moveKeys, movePose, moveBob, moveGo};
